            const id = Number(req.params.id)
            const idx = posts.findIndex((post) => post.id === id)

            const newPosts = posts.map((post, index) =>
              index !== idx
                ? post
                : {
                    ...req.body,
                    id,
                    name: req.body.name || post.name,
                    fetched_at: new Date().toUTCString(),
                  }
